python3 - << 'PYEOF'
import json

# Read flow file
flow_path = '/work/output/artifacts/skill-flow-ixp-routing/invoice-extraction/InvoiceExtraction/InvoiceExtraction/InvoiceExtraction.flow'
with open(flow_path) as f:
    flow = json.load(f)

# Load definitions
with open('/tmp/def-end.json') as f: end_def = json.load(f)['Data']['Node']
with open('/tmp/def-script.json') as f: script_def = json.load(f)['Data']['Node']
with open('/tmp/def-ixp.json') as f: ixp_def = json.load(f)['Data']['Node']

# Append definitions
existing_types = {d['nodeType'] for d in flow['definitions']}
for d in [ixp_def, script_def, end_def]:
    if d['nodeType'] not in existing_types:
        flow['definitions'].append(d)

# Add variable nodes for new user-owned nodes
existing_var_ids = {v['id'] for v in flow['variables']['nodes']}
new_vars = [
    {
        "id": "extractInvoiceFields1.output",
        "type": "object",
        "description": "Extracted invoice fields from IxP",
        "binding": {"nodeId": "extractInvoiceFields1", "outputId": "output"}
    },
    {
        "id": "extractInvoiceFields1.error",
        "type": "object",
        "description": "Extraction error",
        "binding": {"nodeId": "extractInvoiceFields1", "outputId": "error"}
    },
    {
        "id": "buildAccountingPayload1.output",
        "type": "object",
        "description": "Structured invoice payload",
        "binding": {"nodeId": "buildAccountingPayload1", "outputId": "output"}
    }
]
for v in new_vars:
    if v['id'] not in existing_var_ids:
        flow['variables']['nodes'].append(v)

# Add layout entries
for node_id in ['extractInvoiceFields1', 'buildAccountingPayload1', 'end1']:
    if node_id not in flow['layout']['nodes']:
        flow['layout']['nodes'][node_id] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

with open(flow_path, 'w') as f:
    json.dump(flow, f, indent=2)

print("FLOW UPDATED - node count:", len(flow['nodes']))
print("Definitions:", [d['nodeType'] for d in flow['definitions']])
PYEOF

